// pubspec.yaml: geolocator: ^11.0.0
import 'package:geolocator/geolocator.dart';

// ────── One-shot position with the full permission dance ──────
Future<Position?> getMyLocation() async {
  final serviceEnabled = await Geolocator.isLocationServiceEnabled();
  if (!serviceEnabled) {
    await Geolocator.openLocationSettings();
    return null;
  }

  LocationPermission p = await Geolocator.checkPermission();
  if (p == LocationPermission.denied) {
    p = await Geolocator.requestPermission();
    if (p == LocationPermission.denied) return null;
  }
  if (p == LocationPermission.deniedForever) {
    await Geolocator.openAppSettings();
    return null;
  }

  return await Geolocator.getCurrentPosition(
    locationSettings: const LocationSettings(
      accuracy: LocationAccuracy.high,
      timeLimit: Duration(seconds: 15),
    ),
  );
}

// ────── Position stream (foreground rider tracking) ──────
StreamSubscription<Position>? _sub;

void startTracking() {
  final settings = defaultTargetPlatform == TargetPlatform.android
      ? AndroidSettings(
          accuracy: LocationAccuracy.high,
          distanceFilter: 10,               // meters
          intervalDuration: const Duration(seconds: 5),
          foregroundNotificationConfig: const ForegroundNotificationConfig(
            notificationText: 'Tracking delivery',
            notificationTitle: 'Live location',
            enableWakeLock: true,
          ),
        )
      : const AppleSettings(
          accuracy: LocationAccuracy.high,
          distanceFilter: 10,
          pauseLocationUpdatesAutomatically: true,
          activityType: ActivityType.automotiveNavigation,
        );
  _sub = Geolocator.getPositionStream(locationSettings: settings)
      .listen((pos) => print('${pos.latitude}, ${pos.longitude}'));
}

void stopTracking() { _sub?.cancel(); _sub = null; }

